import { useRef } from "react";
import '../index.css'

export default function TrustSection() {
  const sectionRef = useRef(null);

  return (
    <div
      id="dots-png"
      ref={sectionRef}
      className="h-[100vh] sm:h-[280vh]"
      style={{ position: "relative" }}
    >

      {/* ── STICKY background text — always fixed in viewport ── */}
      <div
        className="h-[72vh] sm:h-[100vh]"
        style={{
          position: "sticky",
          top: 0,
          height: "100vh",
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          overflow: "hidden",
          padding: "0 6vw",
          zIndex: 1,
        }}
      >
        {/* ── Static big text — always fully visible ── */}
        <div
          style={{
            position: "relative",
            textAlign: "center",
            zIndex: 1,
            lineHeight: 1.08,
          }}
        >
          {/* Trust, */}
          <div>
            <span
              className="sm:text-[110px] text-[50px]"
              style={{
                fontFamily: "'Inter',sans-serif",
                fontWeight: 600,
                color: "#1A3BB0",
                display: "block",
                lineHeight: 1.0,
              }}
            >
              Trust,
            </span>
          </div>

          {/* however is fragile. */}
          <div
            style={{
              display: "flex",
              alignItems: "baseline",
              justifyContent: "center",
              gap: "0.2em",
              flexWrap: "wrap",
            }}
          >
            <span
              className="sm:text-[105px] text-[50px]"
              style={{
                fontFamily: "'Inter',sans-serif",
                fontWeight: 300,
                color: "#5D5D5D",
                lineHeight: 1.0,
              }}
            >
              however is{" "}
            </span>
            <span
              className="sm:text-[105px] text-[50px]"
              style={{
                fontFamily: "'Inter',sans-serif",
                fontWeight: 700,
                color: "#343434",
                lineHeight: 1.05,
                marginLeft: "14px",
              }}
            >
              fragile.
            </span>
          </div>

          {/* One news headline. */}
          <div>
            <span
              className="sm:text-[105px] text-[50px]"
              style={{
                fontFamily: "'Inter',sans-serif",
                fontWeight: 700,
                color: "#CE1010",
              }}
            >
              One{" "}
            </span>
            <span
              className="sm:text-[105px] text-[50px]"
              style={{
                fontFamily: "'Inter',sans-serif",
                fontWeight: 400,
                color: "#5d5d5d",
              }}
            >
              news headline.
            </span>
          </div>

          {/* One breach */}
          <div>
            <span
              className="sm:text-[105px] text-[50px]"
              style={{
                fontFamily: "'Inter',sans-serif",
                fontWeight: 700,
                color: "#CE1010",
              }}
            >
              One{" "}
            </span>
            <span
              className="sm:text-[105px] text-[50px]"
              style={{
                fontFamily: "'Inter',sans-serif",
                fontWeight: 400,
                color: "#5d5d5d",
              }}
            >
              breach
            </span>
          </div>

          {/* One bad experience. */}
          <div>
            <span
              className="sm:text-[105px] text-[50px]"
              style={{
                fontFamily: "'Inter',sans-serif",
                fontWeight: 700,
                color: "#CE1010",
              }}
            >
              One{" "}
            </span>
            <span
              className="sm:text-[105px] text-[50px]"
              style={{
                fontFamily: "'Inter',sans-serif",
                fontWeight: 400,
                color: "#5d5d5d",
              }}
            >
              bad experience.
            </span>
          </div>

          {/* Footer line */}
          <div style={{ marginTop: 28 }}>
            <p
              style={{
                fontSize: "20px",
                color: "#343434",
                lineHeight: 1.6,
                margin: 0,
              }}
            >
              is all it takes to undo years of hard-earned customer confidence.
            </p>
          </div>
        </div>
      </div>

      {/* ── ANNOTATION 1 — lives OUTSIDE sticky, travels up as user scrolls ──
          Position is absolute within the outer sectionRef div.
          top: "110vh" means it starts just below the screen on load,
          then naturally scrolls upward (over the sticky text) as user scrolls down. */}
      <div
        className="sm:left-[22%] left-[2%]"
        style={{
          position: "absolute",
          top: "110vh",
          zIndex: 10,
          pointerEvents: "none",
          background: "rgba(243,242,242,0.55)",
          backdropFilter: "blur(12px)",
          WebkitBackdropFilter: "blur(12px)",
          borderRadius: 8,
          padding: "16px 22px",
          width: 390,
        }}
      >
        <p
          style={{
            fontSize: 14,
            color: "#343434",
            lineHeight: 1.7,
            fontFamily: "'Inter',sans-serif",
            margin: 0,
          }}
        >
          When speed and scale take priority, due diligence
          slips and blind spots widen. That's exactly what is
          happening in the gig economy today.
        </p>
      </div>

      {/* ── ANNOTATION 2 — starts further down, enters later during scroll ──
          top: "170vh" means it enters the viewport roughly halfway through
          the scroll journey of the section. Adjust to taste. */}
      <div
        style={{
          position: "absolute",
          top: "170vh",
          right: "10%",
          zIndex: 10,
          pointerEvents: "none",
          background: "rgba(243,242,242,0.55)",
          backdropFilter: "blur(12px)",
          WebkitBackdropFilter: "blur(12px)",
          borderRadius: 8,
          padding: "16px 22px",
          width: 390,
        }}
      >
        <p
          style={{
            fontSize: 14,
            color: "#343434",
            lineHeight: 1.7,
            fontFamily: "'Inter',sans-serif",
            margin: 0,
          }}
        >
          Identity swaps, impersonation, and hidden criminal
          histories do more than disrupt operations. They put
          safety, credibility, and customer trust at risk.
        </p>
      </div>

    </div>
  );
}
